def find_git_root(start_path=None):
    """
    通过向上查找 .git 目录来确定 Git 仓库根目录
    """
    if start_path is None:
        start_path = os.getcwd()
    current_path = Path(start_path).resolve()
    # 向上遍历目录
    for parent in [current_path] + list(current_path.parents):
        git_dir = parent / '.git'

