def remove_unbalanced(test_case):
    left_c = test_case.count('[')
    right_c = test_case.count(']')
    if left_c != right_c:
        return test_case.split("[")[0]
    else:
        left_k = test_case.count('(')
        right_k = test_case.count(')')
        if left_k != right_k:
            return test_case.split("[")[0]

